args.sql:
ALTER TABLE fans ADD COLUMN membership_level text;
WITH latest_membership AS (
    SELECT DISTINCT ON (member_fan_pivot) member_fan_pivot, memb_kind 
    FROM membershipandspending 
    ORDER BY member_fan_pivot, member_reg DESC
)
UPDATE fans SET membership_level = lm.memb_kind FROM latest_membership lm WHERE fans.user_registry = lm.member_fan_pivot;

